1.3.28:
```
export function removeFromMatrix(t, e) {
  var r,
    i,
    n = _.find(t, (t, r) => {
      if (_.includes(t, e)) return (i = r), t;
    });
  if (!n) return t;
  if (1 === n.length) {
    if (2 === (r = _.without(t, n))[0].length) {
      let t = r[0];
      r = [[t[0]], [t[1]]];
    }
  } else (r = [...t])[i] = _.without(n, e);
  return r || t;
}
```
1.3.29:
```
export function removeFromMatrix(t, e) {
  var r,
    i = _.find(t, (t, r) => {
      if (_.includes(t, e)) return t;
    });
  if (!i) return t;
  if (1 === i.length) {
    if (2 === (r = _.without(t, i))[0].length) {
      let t = r[0];
      r = [[t[0]], [t[1]]];
    }
  } else (r = [...t])[r] = _.without(i, e);
  return r || t;
}
```

